<template>
  <div class="app-container log-center">
    <div class="page-heading"><div><p>统一查询仓库下发、取消、查询及回传记录。接口成功表示本次交互成功，履约与记账进度请查看“单据当前情况（实时）”。</p></div><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="refresh">刷新</el-button></div>
    <el-form inline size="small" class="filters" @submit.native.prevent="search">
      <el-form-item label="关联单号"><el-input v-model.trim="query.number" clearable placeholder="输入完整单号" @keyup.enter.native="search"><el-select slot="prepend" v-model="query.numberType" style="width:130px"><el-option v-for="(name, code) in numberTypes" :key="code" :label="name" :value="code" /></el-select></el-input></el-form-item>
      <el-form-item label="时间范围"><el-date-picker v-model="dates" :disabled="query.allTime" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" :picker-options="dateOptions" /><el-checkbox v-model="query.allTime" class="all-time">本单全部时间</el-checkbox></el-form-item>
      <el-form-item label="业务类型"><el-select v-model="query.businessType" clearable placeholder="全部业务"><el-option v-for="(name, code) in businesses" :key="code" :label="name" :value="code" /></el-select></el-form-item>
      <el-form-item label="实体仓库"><el-select v-model="query.warehouse" filterable clearable placeholder="全部实体仓"><el-option v-for="w in options.warehouses" :key="w.code" :label="w.name + ' · ' + w.code" :value="w.code" /></el-select></el-form-item>
      <el-form-item label="货主"><el-select v-model="query.owner" filterable clearable placeholder="全部货主"><el-option v-for="o in options.owners" :key="o.code" :label="o.name + ' · ' + o.code" :value="o.code" /></el-select></el-form-item>
      <el-form-item label="仓库连接"><el-select v-model="query.connectionId" filterable clearable placeholder="全部连接"><el-option v-for="c in options.connections" :key="c.id" :label="c.name + (c.enabled ? '' : '（停用）')" :value="String(c.id)" /></el-select></el-form-item>
      <el-form-item label="交互动作"><el-select v-model="query.action" clearable placeholder="全部动作"><el-option v-for="(name, code) in actions" :key="code" :label="name" :value="code" /></el-select></el-form-item>
      <el-form-item label="方向"><el-select v-model="query.direction" clearable placeholder="全部方向"><el-option label="OMS 请求仓库" value="OUT" /><el-option label="仓库通知 OMS" value="IN" /><el-option label="OMS 本地处理" value="LOCAL" /></el-select></el-form-item>
      <el-form-item label="接口结果"><el-select v-model="query.result" clearable placeholder="全部结果"><el-option v-for="(name, code) in results" :key="code" :label="name" :value="code" /></el-select></el-form-item>
      <el-form-item label="环境"><el-select v-model="query.environment" clearable placeholder="全部环境"><el-option label="正式" value="PRODUCTION" /><el-option label="测试" value="TEST" /></el-select></el-form-item>
      <el-form-item label="操作"><el-button type="primary" icon="el-icon-search" :loading="loading" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item>
      <p class="filter-hint">默认最近 24 小时，每次时间查询最多 31 天。输入完整单号或请求编号后，可选择本单全部时间。</p>
    </el-form>
    <el-alert v-if="optionsError" title="筛选选项加载失败，已保留当前查询条件" type="warning" :closable="false"><el-button type="text" @click="loadOptions">重新加载</el-button></el-alert>
    <div class="summary" v-if="summary"><div class="summary-item"><span>筛选范围内交互</span><strong>{{ summary.total }}</strong></div><div v-for="(name, code) in results" :key="code" :class="['summary-item', resultTone(code)]"><span>{{ name }}</span><strong>{{ count(code) }}</strong></div></div>
    <el-alert v-if="loadError" :title="loadError" type="error" :closable="false" show-icon />
    <div class="records" v-loading="loading"><wms-log-table :rows="rows" :options="options" @detail="show" /><div class="pages"><span>第 {{ cursors.length + 1 }} 页 · 每页 50 条</span><el-button size="small" :disabled="!cursors.length || loading" @click="previous">上一页</el-button><el-button size="small" :disabled="!next || loading" @click="nextPage">下一页</el-button></div></div>
    <el-drawer title="仓库交互详情与单据链路" :visible.sync="detailVisible" size="min(1180px, 96vw)" append-to-body>
      <div class="detail" v-loading="detailLoading">
        <el-alert v-if="detailError" :title="detailError" type="error" :closable="false" />
        <template v-if="detail">
          <div class="detail-heading"><strong>{{ detail.ticket_sn || '未关联业务单据' }}</strong><el-tag size="small" :type="resultTone(detail.result)">{{ actions[detail.action] || detail.action }} · {{ results[detail.result] || detail.result }}</el-tag><el-button v-if="detail.process_id" size="small" @click="$router.push({path:'/oms-inventory/kitProcess',query:{id:detail.process_id}});detailVisible=false">打开套装加工单</el-button><el-button v-if="detail.shipment_id" v-hasPermi="['order:order:query']" size="small" @click="openDocument">打开发货单</el-button><el-button v-else-if="detail.ticket_id" v-hasPermi="['warehouse:tickets:query']" size="small" @click="openDocument">打开入库单</el-button><el-button v-if="detail.order_id" v-hasPermi="['order:order:query']" size="small" @click="openOrder">打开业务订单</el-button></div>
          <el-descriptions :column="2" border size="small"><el-descriptions-item label="本次时间">{{ detail.create_time }}</el-descriptions-item><el-descriptions-item label="请求编号">{{ detail.request_id }}</el-descriptions-item><el-descriptions-item label="连接 / 环境">{{ detail.connection_name }} / {{ providerName(detail.provider) }} / {{ detail.environment === 'PRODUCTION' ? '正式' : detail.environment === 'TEST' ? '测试' : '未知' }}</el-descriptions-item><el-descriptions-item label="方向 / 耗时">{{ detail.direction === 'LOCAL' ? 'OMS 本地处理' : detail.direction === 'IN' ? '仓库 → OMS' : 'OMS → 仓库' }} / {{ detail.duration_ms }} ms</el-descriptions-item><el-descriptions-item label="外部仓库 / 货主">{{ detail.external_warehouse || '—' }} / {{ detail.external_owner || '—' }}</el-descriptions-item><el-descriptions-item label="仓库单号">{{ detail.external_order || '—' }}</el-descriptions-item><el-descriptions-item label="本次原因" :span="2">{{ detail.error_info || '—' }}</el-descriptions-item></el-descriptions>
          <el-alert v-if="detail.result_summary" class="progress-notice" title="本次交互结果（发生时）" :description="detail.result_summary" type="info" :closable="false" show-icon />
          <el-alert class="progress-notice" title="当前单据处理进度（不代表本次交互发生时的状态）" :description="detail.business_progress" :type="detail.business_tone === 'danger' ? 'error' : detail.business_tone" :closable="false" show-icon />
          <el-tabs v-model="detailTab"><el-tab-pane label="单据交互链路" name="chain"><p class="muted">同一连接、业务类型与执行单的全部时间记录。按最近时间排序，每次请求和重试独立保留。</p><el-alert v-if="!detail.ticket_sn" title="该回传暂未关联单据，可按连接和时间继续排查；不会凭未经验证的报文关联其他单据。" type="warning" :closable="false" /><wms-log-table v-loading="chainLoading" :rows="chainRows" :options="options" @detail="show" /><el-button v-if="chainNext" :loading="chainLoading" class="more-chain" @click="loadChain(true)">加载更早记录</el-button></el-tab-pane><el-tab-pane label="本次交互报文" name="payload"><template v-if="canPayload"><el-button v-if="!payload" :loading="payloadLoading" @click="loadPayload">加载已脱敏报文</el-button><template v-else><div class="payload-tools"><el-radio-group v-model="payloadPart" size="small"><el-radio-button label="request_body">请求报文</el-radio-button><el-radio-button label="response_body">响应报文</el-radio-button></el-radio-group><el-input v-model="payloadSearch" clearable placeholder="查找报文内容" size="small" /><el-button size="small" @click="copyPayload">复制报文</el-button></div><pre><template v-for="(part, i) in payloadSegments"><mark v-if="part.match" :key="i">{{ part.text }}</mark><template v-else>{{ part.text }}</template></template></pre><p class="muted">报文已脱敏，最多保留 1 MB；列表不加载报文。此处没有重试、取消或记账操作。</p></template></template><el-alert v-else title="当前账号没有查看交互报文权限" type="info" :closable="false" /></el-tab-pane></el-tabs>
        </template>
      </div>
    </el-drawer>
  </div>
</template>
<script>
import { logCenter, logCenterSummary, logCenterOptions, logCenterDetail, interactionLog } from '@/api/warehouse/integration'
import { checkPermi } from '@/utils/permission'
import WmsLogTable from './WmsLogTable'
import { actions, results, businesses, resultTone, providerName } from './wmsLogLabels'
const defaults = () => ({ numberType: 'DOCUMENT', number: '', allTime: false, businessType: '', warehouse: '', owner: '', connectionId: '', action: '', direction: '', result: '', environment: '' })
function date(value) { const d = new Date(value); const pad = n => String(n).padStart(2, '0'); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}` }
function recent(hours) { return [date(Date.now() - hours * 3600000), date(Date.now())] }
export default {
  name: 'WmsLogCenter', components: { WmsLogTable },
  data() { return { query: defaults(), dates: recent(24), applied: {}, actions, results, businesses, numberTypes: { DOCUMENT: '执行单号 / XS / JG', REFUND:'退款单号 / TK', EXCHANGE: '换货单号', ARRIVAL: '到货单号', PURCHASE: '采购单号', ORDER: 'OMS 订单号', PLATFORM: '平台订单号', WAREHOUSE: '仓库单号', REQUEST: '请求编号' }, options: { connections: [], warehouses: [], owners: [] }, optionsError: false, loading: false, loadError: '', rows: [], summary: null, cursors: [], cursor: null, next: null, sequence: 0, detailVisible: false, detailLoading: false, detailError: '', detail: null, detailTab: 'chain', detailSequence: 0, chainRows: [], chainNext: null, chainLoading: false, payload: null, payloadLoading: false, payloadPart: 'request_body', payloadSearch: '', dateOptions: { shortcuts: [24, 72, 168].map(hours => ({ text: `最近 ${hours === 24 ? '24 小时' : hours / 24 + ' 天'}`, onClick(picker) { picker.$emit('pick', [new Date(Date.now() - hours * 3600000), new Date()]) } })) } } },
  computed: {
    canPayload() { return checkPermi(['warehouse:wms:payload']) },
    payloadText() { const raw = this.payload && this.payload[this.payloadPart]; if (!raw) return '尚无报文'; try { return JSON.stringify(JSON.parse(raw), null, 2) } catch (_) { if (raw.trim().startsWith('<') && !new DOMParser().parseFromString(raw, 'application/xml').querySelector('parsererror')) { let depth = 0; return raw.replace(/>\s*</g, '>\n<').split('\n').map(line => { if (/^<\//.test(line)) depth = Math.max(0, depth - 1); const formatted = '  '.repeat(depth) + line; if (/^<[^!?/][^>]*>/.test(line) && !/<\//.test(line) && !/\/>$/.test(line)) depth = Math.min(60, depth + 1); return formatted }).join('\n') } return raw } },
    payloadSegments() { const s = this.payloadText; const key = this.payloadSearch; if (!key) return [{ text: s }]; const rows = []; let offset = 0; let found; while ((found = s.toLowerCase().indexOf(key.toLowerCase(), offset)) >= 0 && rows.length < 2000) { rows.push({ text: s.slice(offset, found) }, { text: s.slice(found, found + key.length), match: true }); offset = found + key.length } rows.push({ text: s.slice(offset) }); return rows }
  },
  watch: { '$route.query'() { if (this.$route.path === '/oms-supplychain/wmsLogs') this.readRoute() } },
  created() { this.loadOptions(); this.readRoute() },
  methods: {
    resultTone, providerName,
    count(code) { const row = (this.summary.counts || []).find(r => r.result === code); return row ? row.log_count : 0 },
    async loadOptions() { this.optionsError = false; try { this.options = (await logCenterOptions()).data } catch (_) { this.optionsError = true } },
    readRoute() { const q = defaults(); Object.keys(q).forEach(k => { if (this.$route.query[k] !== undefined) q[k] = k === 'allTime' ? this.$route.query[k] === 'true' : this.$route.query[k] }); this.query = q; this.dates = this.$route.query.begin && this.$route.query.end ? [this.$route.query.begin, this.$route.query.end] : recent(24); this.applied = { ...q, ...(q.allTime ? {} : { begin: this.dates[0], end: this.dates[1] }) }; this.refresh() },
    search() { if (this.query.allTime && !this.query.number) return this.$message.warning('本单全部时间查询需要填写完整单号'); if (!this.query.allTime && (!this.dates || this.dates.length !== 2 || new Date(this.dates[1]) <= new Date(this.dates[0]) || new Date(this.dates[1]) - new Date(this.dates[0]) > 31 * 86400000)) return this.$message.warning('请选择不超过 31 天的有效时间范围'); const q = { ...this.query, allTime: String(this.query.allTime), ...(this.query.allTime ? {} : { begin: this.dates[0], end: this.dates[1] }) }; this.$router.replace({ path: '/oms-supplychain/wmsLogs', query: q }).catch(() => this.readRoute()) },
    reset() { this.query = defaults(); this.dates = recent(24); this.search() },
    refresh() { if (!this.$route.query.begin && !this.applied.allTime) { this.dates = recent(24); this.applied = { ...this.applied, begin: this.dates[0], end: this.dates[1] } } this.cursors = []; this.cursor = null; this.next = null; this.load(true) },
    async load(withSummary = false) { const seq = ++this.sequence; this.loading = true; this.loadError = ''; try { const [page, summary] = await Promise.all([logCenter({ ...this.applied, ...(this.cursor || {}) }), withSummary ? logCenterSummary(this.applied) : Promise.resolve(null)]); if (seq !== this.sequence) return; this.rows = page.data.rows; this.next = page.data.next; if (summary) this.summary = summary.data } catch (_) { if (seq === this.sequence) { this.rows = []; this.summary = null; this.next = null; this.loadError = '日志加载失败，请调整条件或刷新重试' } } finally { if (seq === this.sequence) this.loading = false } },
    nextPage() { if (!this.next || this.loading) return; this.cursors.push(this.cursor); this.cursor = this.next; this.load() },
    previous() { if (!this.cursors.length || this.loading) return; this.cursor = this.cursors.pop(); this.load() },
    async show(row) { const seq = ++this.detailSequence; this.detailVisible = true; this.detailLoading = true; this.detailError = ''; this.detail = null; this.chainRows = []; this.chainNext = null; this.payload = null; this.payloadSearch = ''; this.detailTab = 'chain'; try { const d = await logCenterDetail(row.id); if (seq !== this.detailSequence) return; this.detail = d.data; await this.loadChain(false, seq) } catch (_) { if (seq === this.detailSequence) this.detailError = '详情加载失败，请重新打开该条日志' } finally { if (seq === this.detailSequence) this.detailLoading = false } },
    async loadChain(more = false, seq = this.detailSequence) { if (!this.detail || !this.detail.ticket_sn) { this.chainRows = this.detail ? [this.detail] : []; return } this.chainLoading = true; const d = this.detail; try { const r = await logCenter({ numberType: 'DOCUMENT', number: d.ticket_sn, allTime: true, businessType: d.business_type, connectionId: d.connection_id, ...(more ? this.chainNext : {}) }); if (seq === this.detailSequence) { this.chainRows = more ? this.chainRows.concat(r.data.rows) : r.data.rows; this.chainNext = r.data.next } } finally { if (seq === this.detailSequence) this.chainLoading = false } },
    async loadPayload() { if (!this.canPayload || !this.detail || this.payloadLoading) return; const seq = this.detailSequence; this.payloadLoading = true; try { const r = await interactionLog(this.detail.id); if (seq === this.detailSequence) this.payload = r.data } finally { this.payloadLoading = false } },
    async copyPayload() { try { await navigator.clipboard.writeText(this.payloadText); this.$message.success('已复制脱敏报文') } catch (_) { this.$message.warning('浏览器未允许复制，请在报文区域手工复制') } },
    openDocument() { const d = this.detail; this.detailVisible = false; this.$router.push(d.shipment_id ? { path: '/oms-order/shipments', query: { number: d.ticket_sn } } : { path: '/oms-supplychain/wmsTickets', query: { sn: d.ticket_sn, documentId: d.ticket_id } }) },
    openOrder() { this.detailVisible = false; this.$router.push({ path: '/oms-order/business', query: { view: 'business', orderId: this.detail.order_id } }) }
  }
}
</script>
<style scoped>
.page-heading,.detail-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.page-heading h2{font-size:20px;margin:0 0 8px}.page-heading p,.filter-hint,.muted{font-size:13px;color:#7a8799;line-height:1.8}.page-heading{margin-bottom:20px}.filters{padding:18px 20px 4px;background:#fff;border:1px solid #e7ecf3;border-radius:8px}.filters ::v-deep .el-form-item__label{display:block;text-align:left;float:none;line-height:25px}.filters ::v-deep .el-form-item{vertical-align:top;margin-right:16px}.filters ::v-deep .el-select{width:175px}.filters ::v-deep .el-date-editor{width:350px}.filters ::v-deep .el-input-group{width:355px}.all-time{display:block;margin-top:6px}.filter-hint{margin:0 0 12px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin:18px 0}.summary-item{background:#f5f8fc;border:1px solid #e3eaf3;border-radius:8px;padding:14px 18px;display:flex;flex-direction:column;gap:8px;color:#78879d;font-size:13px}.summary-item strong{font-size:26px;color:#34455e}.summary-item.danger strong{color:#c54646}.summary-item.warning strong{color:#b67c14}.summary-item.success strong{color:#278455}.records{background:#fff;border-radius:8px;padding:16px}.pages{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:16px;font-size:13px;color:#77879a}.detail{padding:0 24px 24px}.detail-heading{justify-content:flex-start;margin-bottom:18px;overflow-wrap:anywhere}.detail ::v-deep .el-descriptions-item__content{overflow-wrap:anywhere}.progress-notice{margin:18px 0}.payload-tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:12px 0}.payload-tools .el-input{width:230px}pre{padding:16px;background:#f5f7fa;border:1px solid #e4e9f1;border-radius:6px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:55vh;overflow:auto;font-size:12px;line-height:1.7}mark{background:#ffe4a3}.more-chain{margin-top:16px}@media(max-width:900px){.summary{grid-template-columns:repeat(3,1fr)}.filters ::v-deep .el-date-editor,.filters ::v-deep .el-input-group{max-width:100%}.detail{padding:0 12px 20px}}
</style>
